NEWF = json.loads(r"""{"inc/setuplink.php": "<?php\n/* (2.99.632 - LENH 632, anh Logan 02/11 19:19-19:28) LINK CAI DAT TIEM: one link (/setup/?t=<token>) on the salon's OWN address, no login.\n   The salon owner picks the turn rules (part \"turn\") and fixes / adds the techs (part \"staff\"); each part is saved ONCE.\n   Safety:\n   - the token: 32 random bytes, only its sha256 kept (setting setup_link), 7 days, a new link = the old one dead; this salon's database only\n     (every salon has its own) + the request's host must be the host of this salon's own address (pub_url()).\n   - saving goes through the SAME code as the owner's screens (api save_settings / save_staff_one / remove_staff): the same checks, the same\n     audit lines, the same payroll history. Only the keys / fields below go through; anything else is dropped before.\n   - before a part is saved: the old values kept (setup_turn_prev / setup_staff_prev) -> Settings -> Turn rules \"Undo the link setup\".\n   - money, customers, appointments: never touched here. No PIN: each tech sets their own PIN on /tech/ as today. */\ndeclare(strict_types=1);\nif (!function_exists('audit')) require_once __DIR__ . '/audit.php';\n\nconst SETUP_DAYS = 7;\nconst SETUP_PARTS = ['turn', 'staff'];\n/** part \"turn\": the keys the link may write (BANG-MAP-632 + TRA-LOI-632) */\nconst SETUP_TURN_KEYS = ['turn_tie', 'turn_min', 'turn_under', 'turn_multi', 'turn_multi_amt', 'turn_svc_amt', 'turn_req_mode', 'turn_hold_min', 'turn_rare_keep',\n    'turn_pre_open', 'turn_skip_max', 'turn_brk_max', 'turn_auto_on', 'ck_pick_tech'];\n/** part \"staff\", the whole salon: week start + closed days (hours: only \"closed\" may change, never the times) */\nconst SETUP_SHOP_KEYS = ['payroll_week_start', 'hours'];\n/** part \"staff\", one tech: the fields of save_staff_one the link may send (never a PIN, legal name, address, color, photo) */\nconst SETUP_STAFF_FIELDS = ['id', 'name', 'phone', 'offDays', 'skillAll', 'skillCats', 'skillPick', 'commission', 'payMethod', 'mixCheck', 'payNote', 'online', 'deskOk', 'voice'];\n\nfunction setup_get(): array { $j = json_decode((string)setting('setup_link'), true); return is_array($j) ? $j : []; }\nfunction setup_put(array $j): void { set_setting('setup_link', json_encode($j)); }\nfunction setup_host(): string { return strtolower((string)parse_url(pub_url(), PHP_URL_HOST)); }\nfunction setup_req_host(): string { return strtolower((string)preg_replace('/:\\d+$/', '', rtrim(trim((string)($_SERVER['HTTP_HOST'] ?? '')), '.'))); }\n/** Owner: a new link (the old one stops now). Returns the full URL on this salon's own address. */\nfunction setup_new(): string {\n    $t = bin2hex(random_bytes(32));\n    setup_put(['h' => hash('sha256', $t), 'exp' => time() + SETUP_DAYS * 86400, 'made' => now_str(), 'done' => []]);\n    audit('turn_setup', 'Setup link', '', 'new link (7 days)');\n    return rtrim(pub_url(), '/') . '/setup/?t=' . $t;\n}\n/** The token of this request: OK -> the link row, else null (wrong / expired / used / another address). Never says why to the visitor. */\nfunction setup_check(string $t): ?array {\n    $j = setup_get();\n    if ($t === '' || strlen($t) < 32 || !isset($j['h']) || !hash_equals((string)$j['h'], hash('sha256', $t))) return null;\n    if ((int)($j['exp'] ?? 0) < time()) return null;\n    if (!array_diff(SETUP_PARTS, (array)($j['done'] ?? []))) return null;   // every part saved: the link is used up\n    $hs = setup_host(); if ($hs !== '' && setup_req_host() !== $hs) return null;   // only on this salon's own address\n    return $j;\n}\nfunction setup_part_done(string $part): void { $j = setup_get(); $d = (array)($j['done'] ?? []); if (!in_array($part, $d, true)) $d[] = $part; $j['done'] = $d; setup_put($j); }\n\n/* ---------- what the page shows: the salon's CURRENT values (not the defaults) ---------- */\nfunction setup_turn_now(): array {\n    if (!function_exists('tq_cfg')) require_once __DIR__ . '/turnq.php';\n    $c = tq_cfg(); $hm = trim((string)setting('turn_hold_min'));\n    return ['turn_tie' => $c['tie'], 'turn_min' => $c['min'], 'turn_under' => $c['under'], 'turn_multi' => $c['multi'], 'turn_multi_amt' => $c['per'],\n        'turn_svc_amt' => (float)(setting('turn_svc_amt') ?: 30), 'turn_req_mode' => $c['reqMode'], 'turn_hold_min' => $hm === '' ? 20 : (int)$hm,\n        'turn_rare_keep' => $c['rareKeep'] ? 1 : 0, 'turn_pre_open' => setting('turn_pre_open') === '1' ? 1 : 0, 'turn_skip_max' => (int)setting('turn_skip_max'),\n        'turn_brk_max' => (int)setting('turn_brk_max'), 'turn_auto_on' => setting('turn_auto_on') === '0' ? 0 : 1, 'ck_pick_tech' => setting('ck_pick_tech') === '1' ? 1 : 0];\n}\nfunction setup_staff_now(): array {\n    if (!defined('PAY_METHODS')) require_once __DIR__ . '/payroll.php';\n    $o = [];\n    foreach (q('SELECT * FROM staff WHERE active = 1 ORDER BY sort, id')->fetchAll() as $s) $o[] = ['id' => (int)$s['id'], 'name' => (string)$s['name'], 'phone' => (string)$s['phone'],\n        'offDays' => ids_list((string)$s['off_days']), 'skillAll' => (int)($s['skill_all'] ?? 1), 'skillCats' => array_values(array_filter(explode('|', (string)($s['skill_cats'] ?? '')))), 'skillPick' => ids_list((string)($s['skill_pick'] ?? '')),\n        'commission' => (float)$s['commission_pct'], 'payMethod' => (string)$s['pay_method'], 'mixCheck' => (float)$s['mix_check_pct'] < 0 ? '' : (float)$s['mix_check_pct'],\n        'payNote' => (string)$s['pay_note'], 'online' => (int)$s['online'], 'deskOk' => (int)$s['desk_ok'], 'voice' => staff_voice((int)$s['id'])];\n    return $o;\n}\nfunction setup_shop_now(): array {\n    if (!function_exists('payroll_start_dow')) require_once __DIR__ . '/payroll.php';\n    $h = json_decode((string)setting('hours'), true); $closed = [];\n    for ($d = 0; $d < 7; $d++) if (!empty($h[(string)$d]['closed'])) $closed[] = $d;\n    return ['payroll_week_start' => payroll_start_dow(), 'closed' => $closed];\n}\n/** Only the allowed keys of the request; the hours: the salon's own times kept, only \"closed\" from the page. */\nfunction setup_pick(array $in, array $keys): array { return array_intersect_key($in, array_flip($keys)); }\nfunction setup_shop_in(array $in): array {\n    $o = setup_pick($in, ['payroll_week_start']);\n    if (array_key_exists('closed', $in)) { $cl = array_map('intval', (array)$in['closed']); $h = json_decode((string)setting('hours'), true); $h = is_array($h) ? $h : []; $x = [];\n        for ($d = 0; $d < 7; $d++) { $r = (array)($h[(string)$d] ?? []); $x[(string)$d] = ['closed' => in_array($d, $cl, true), 'open' => (string)($r['open'] ?? '09:00'), 'close' => (string)($r['close'] ?? '19:00')]; }\n        $o['hours'] = $x; }\n    return $o;\n}\n", "inc/api/setuplink.php": "<?php\n// (2.99.632 - LENH 632) api.php actions of the salon setup link (/setup/?t=...): inc/setuplink.php. Variables ($in, $method, $action...) are api.php's.\n// The token actions save through the SAME actions as the owner's screens (save_settings, save_staff_one, remove_staff): only the allowed keys go through.\ndeclare(strict_types=1);\nif (!defined('API_MAIN')) { http_response_code(404); exit; }\nrequire_once APP_ROOT . '/inc/setuplink.php';\n\nif ($action === 'setup_new') { need_admin(); json_out(['ok' => true, 'url' => setup_new()]); }\nif ($action === 'setup_prev') { need_admin(); // Settings -> Turn rules \"Undo the link setup\": the old values, saved back by the page with save_settings / save_staff_one\n    $t = json_decode((string)setting('setup_turn_prev'), true); $s = json_decode((string)setting('setup_staff_prev'), true);\n    $nt = json_decode((string)setting('turn_setup_notes'), true); json_out(['ok' => true, 'notes' => is_array($nt) ? $nt : null, 'turn' => is_array($t) ? $t : null, 'staff' => is_array($s) ? $s : null, 'link' => (static function () { $j = setup_get(); return $j ? ['made' => (string)($j['made'] ?? ''), 'exp' => date('Y-m-d H:i', (int)($j['exp'] ?? 0)), 'done' => (array)($j['done'] ?? [])] : null; })()]); }\nif ($action === 'setup_prev_clear') { need_admin(); $w = (string)($in['part'] ?? ''); if (in_array($w, ['turn', 'staff'], true)) { set_setting('setup_' . $w . '_prev', ''); audit('turn_setup', 'Setup link', $w, 'undone by the owner'); } json_out(['ok' => true]); }\n\n/* ---------- the link itself (no login: the token is the key) ---------- */\n$setupTok = (string)($in['t'] ?? ($_GET['t'] ?? ''));\n$setupL = setup_check($setupTok);\nif (!$setupL) fail('This link does not work any more \u2013 ask the salon for a new one. \u00b7 Link n\u00e0y kh\u00f4ng c\u00f2n d\u00f9ng \u0111\u01b0\u1ee3c \u2013 xin ti\u1ec7m g\u1eedi link m\u1edbi.', 403);\n$setupDone = (array)($setupL['done'] ?? []);\nif ($action === 'setup_info') {\n    if (!function_exists('skill_cats')) require_once APP_ROOT . '/inc/core/staff-services.php';\n    if (!defined('PAY_METHODS')) require_once APP_ROOT . '/inc/payroll.php';\n    $cats = []; foreach (skill_cats() as $k => $c) if (empty($c['hidden'])) $cats[] = ['key' => $k, 'icon' => (string)$c['icon']];\n    json_out(['ok' => true, 'salon' => trim((string)setting('salon_name')) ?: 'Salon', 'logo' => logo_url('192'), 'done' => $setupDone, 'exp' => date('Y-m-d', (int)$setupL['exp']),\n        'turn' => setup_turn_now(), 'staff' => setup_staff_now(), 'shop' => setup_shop_now(), 'cats' => $cats, 'payMethods' => PAY_METHODS]);\n}\nif ($method !== 'POST') fail('POST only.', 405);\napp_lock('setup'); // one save at a time (two phones on the same link wait for each other)\n$setupPart = $action === 'setup_turn' ? 'turn' : 'staff';\nif (in_array($setupPart, $setupDone, true)) fail('This part is already saved. \u00b7 Ph\u1ea7n n\u00e0y \u0111\u00e3 l\u01b0u r\u1ed3i.', 409);\nactor_set('admin', 'Setup link');\n$setupSay = function (string $what) { try { notify_admin('setup', '\ud83d\udd17 ' . $what, 0, ['title' => '\ud83d\udd17 Setup link', 'body' => $what, 'url' => '?settings=turn']); } catch (Throwable $e) { error_log('632 push: ' . $e->getMessage()); } };\n/* the delegated action runs exactly as from the owner's screen (incl. the demo salon's refusals) */\nfunction setup_go(string $act): void { if (is_demo_site()) { require_once APP_ROOT . '/inc/demo.php'; demo_refuse($act); } define('NF_SETUP_OK', $act); }\n$setupPrevStaff = function (): array { $p = json_decode((string)setting('setup_staff_prev'), true); return is_array($p) && ($p['link'] ?? '') === (string)setup_get()['made'] ? $p : ['link' => (string)setup_get()['made'], 'rows' => [], 'new' => [], 'off' => [], 'shop' => null]; };\n\nif ($action === 'setup_turn') {\n    $notes = []; foreach (array_slice((array)($in['notes'] ?? []), 0, 20) as $n) if (is_array($n)) $notes[] = ['q' => mb_substr((string)($n['q'] ?? ''), 0, 8), 'pick' => mb_substr((string)($n['pick'] ?? ''), 0, 20), 'text' => mb_substr(trim((string)($n['text'] ?? '')), 0, 500)];\n    $old = setup_turn_now(); $in = setup_pick($in, SETUP_TURN_KEYS);\n    if (!$in && !$notes) fail('Nothing to save. \u00b7 Kh\u00f4ng c\u00f3 g\u00ec \u0111\u1ec3 l\u01b0u.');\n    register_shutdown_function(function () use ($old, $in, $setupSay, $notes) {\n        if (http_response_code() !== 200) return; // refused by the Settings checks: nothing was saved, the link still works\n        set_setting('turn_setup_notes', json_encode(['at' => now_str(), 'notes' => $notes], JSON_UNESCAPED_UNICODE)); // what the app does not have yet: NailFlow sets it up later\n        $new = setup_turn_now(); $ch = [];\n        foreach ($old as $k => $v) if ((string)$v !== (string)$new[$k]) { $ch[] = $k; audit('turn_setup', $k, (string)$v, (string)$new[$k]); }\n        set_setting('setup_turn_prev', json_encode($old)); setup_part_done('turn');\n        $setupSay('Turn rules updated through the setup link' . ($ch ? ' (' . count($ch) . ' changed)' : ' (nothing changed)') . ' \u00b7 Lu\u1eadt turn \u0111\u00e3 c\u1eadp nh\u1eadt qua link c\u00e0i \u0111\u1eb7t');\n    });\n    setup_go('save_settings'); $action = 'save_settings'; require __DIR__ . '/settings.php'; exit;\n}\nif ($action === 'setup_shop') {\n    $in = setup_shop_in($in); if (!$in) fail('Nothing to save. \u00b7 Kh\u00f4ng c\u00f3 g\u00ec \u0111\u1ec3 l\u01b0u.');\n    $p = $setupPrevStaff(); if ($p['shop'] === null) { $h = setup_shop_now(); $p['shop'] = ['payroll_week_start' => $h['payroll_week_start'], 'hours' => json_decode((string)setting('hours'), true)]; set_setting('setup_staff_prev', json_encode($p)); }\n    setup_go('save_settings'); $action = 'save_settings'; require __DIR__ . '/settings.php'; exit;\n}\nif ($action === 'setup_staff_one' || $action === 'setup_staff_off') {\n    $sid = (int)($in['id'] ?? 0); $row = $sid ? q('SELECT * FROM staff WHERE id = ?', [$sid])->fetch() : null;\n    if ($sid && !$row) fail('Tech not found. \u00b7 Kh\u00f4ng th\u1ea5y th\u1ee3 n\u00e0y.', 404); // an id of another salon / made up: never written\n    if ($row && !(int)$row['active']) fail('Tech not found. \u00b7 Kh\u00f4ng th\u1ea5y th\u1ee3 n\u00e0y.', 404); // a tech turned off: not edited / turned off through the link\n    if ($action === 'setup_staff_off' && !$row) fail('Tech not found. \u00b7 Kh\u00f4ng th\u1ea5y th\u1ee3 n\u00e0y.', 404);\n    $p = $setupPrevStaff();\n    if ($row && !isset($p['rows'][(string)$sid])) { foreach (setup_staff_now() as $x) if ($x['id'] === $sid) $p['rows'][(string)$sid] = $x; }\n    if ($action === 'setup_staff_off') {\n        $p['off'][] = $sid; set_setting('setup_staff_prev', json_encode($p)); $in = ['id' => $sid];\n        setup_go('remove_staff'); $action = 'remove_staff'; require __DIR__ . '/staffadmin.php'; exit;\n    }\n    $in = setup_pick($in, SETUP_STAFF_FIELDS);\n    $nm = strtoupper(trim(mb_substr((string)($in['name'] ?? ''), 0, 40)));\n    if ($nm !== '' && q('SELECT 1 FROM staff WHERE active = 1 AND UPPER(name) = ? AND id <> ?', [$nm, $sid])->fetchColumn()) fail('Another tech already has the name ' . $nm . '. \u00b7 \u0110\u00e3 c\u00f3 th\u1ee3 t\u00ean ' . $nm . '.');\n    if (array_key_exists('skillAll', $in) && empty($in['skillAll']) && !array_filter((array)($in['skillCats'] ?? [])) && !array_filter((array)($in['skillPick'] ?? []))) fail('Turn on at least one kind of service (or \"Can do ALL services\"). \u00b7 Ch\u1ecdn \u00edt nh\u1ea5t 1 lo\u1ea1i d\u1ecbch v\u1ee5.');\n    if ($row && !array_key_exists('skillPick', $in)) $in['skillPick'] = ids_list((string)($row['skill_pick'] ?? '')); // the services picked one by one stay\n    /* (2.99.632 SUA-632, CHAT 20:30) save_staff_one writes some fields even when they are not sent (notify: !empty -> 0; offDays, payMethod, payNote, mixCheck, online: defaults):\n       a tech of the salon keeps every field the link did not send (its current values), and \"Send this tech alerts\" is never changed by the link;\n       a new tech gets alerts ON like \"+ Add\" on the Staff screen. */\n    if ($row) { foreach (setup_staff_now() as $x) if ($x['id'] === $sid) foreach ($x as $k => $v) if (!array_key_exists($k, $in)) $in[$k] = $v; $in['notify'] = (int)$row['notify']; }\n    else $in['notify'] = 1;\n    set_setting('setup_staff_prev', json_encode($p));\n    if (!$sid) register_shutdown_function(function () use ($nm, $setupPrevStaff) { if (http_response_code() !== 200) return;\n        $id = (int)q('SELECT MAX(id) FROM staff WHERE name = ?', [$nm])->fetchColumn(); $p = $setupPrevStaff(); if ($id && !in_array($id, $p['new'], true)) { $p['new'][] = $id; set_setting('setup_staff_prev', json_encode($p)); }\n        audit('turn_setup', 'Tech ' . $nm, '', 'added through the setup link'); });\n    setup_go('save_staff_one'); $action = 'save_staff_one'; require __DIR__ . '/staffadmin.php'; exit;\n}\nif ($action === 'setup_staff_end') {\n    $p = $setupPrevStaff(); setup_part_done('staff');\n    audit('turn_setup', 'Setup link', '', 'staff list saved (' . count($p['rows']) . ' changed, ' . count($p['new']) . ' new, ' . count($p['off']) . ' off)');\n    $setupSay('Staff list updated through the setup link \u00b7 Danh s\u00e1ch th\u1ee3 \u0111\u00e3 c\u1eadp nh\u1eadt qua link c\u00e0i \u0111\u1eb7t');\n    json_out(['ok' => true]);\n}\nfail('Unknown action', 404);\n", "setup/index.php": "<?php\n/* (2.99.632 - LENH 632) The salon setup link: /setup/?t=<token> on the salon's OWN address. No login \u2013 the token is checked by api.php\n   (setup_info / setup_turn / setup_shop / setup_staff_one / setup_staff_off / setup_staff_end). Nothing about the salon is in this file:\n   a wrong / old link shows only one short line. */\ndeclare(strict_types=1);\nheader('Content-Type: text/html; charset=utf-8'); header('Cache-Control: no-store'); header('X-Robots-Tag: noindex, nofollow'); header('Referrer-Policy: no-referrer');\n?><!doctype html>\n<html lang=\"vi\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex,nofollow\"><meta name=\"referrer\" content=\"no-referrer\"><title>Setup</title>\n<style>\n:root{--bg:#F2F2F7;--card:#fff;--ink:#1C1C1E;--sub:#6C6C70;--line:#E5E5EA;--blue:#2F6FB5;--green:#1E8E3E;--red:#C62828;--amber:#8A5A00}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.45 -apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Arial,sans-serif}\nmain{max-width:640px;margin:0 auto;padding:12px 16px 120px}\nheader{display:flex;align-items:center;gap:12px;padding:8px 0 4px}header img{width:52px;height:52px;border-radius:12px;object-fit:cover;background:#fff}\nh1{font-size:22px;margin:0}h2{font-size:19px;margin:26px 0 8px}.sub{color:var(--sub);font-size:15px}\n.lang{margin-left:auto;border:1px solid var(--line);background:#fff;border-radius:18px;padding:6px 12px;font-size:15px}\n.q{background:var(--card);border-radius:14px;padding:14px 14px 10px;margin:10px 0}.q h3{font-size:17px;margin:0 0 8px}\nlabel.o{display:flex;gap:10px;align-items:flex-start;padding:9px 6px;border-top:1px solid var(--line);cursor:pointer}label.o:first-of-type{border-top:0}\nlabel.o input{margin-top:4px;width:20px;height:20px;flex:none}.tag{font-size:12px;font-weight:600;border-radius:6px;padding:1px 6px;margin-left:6px;white-space:nowrap}\n.pop{background:#E3F1E6;color:var(--green)}.now{background:#E6EEF8;color:var(--blue)}.later{background:#FFF3D6;color:var(--amber)}\ninput[type=number],input[type=text],input[type=tel],textarea,select{font:inherit;border:1px solid var(--line);border-radius:10px;padding:8px 10px;width:100%;background:#fff}\ninput.n{width:92px;display:inline-block}textarea{min-height:60px}\n.btn{font:inherit;font-weight:600;border:0;border-radius:12px;padding:13px 18px;background:var(--blue);color:#fff;width:100%;margin-top:10px}\n.btn.alt{background:#fff;color:var(--blue);border:1px solid var(--line)}.btn:disabled{opacity:.5}\n.ok{background:#E3F1E6;color:var(--green);border-radius:12px;padding:12px;margin:10px 0}.err{background:#FDECEA;color:var(--red);border-radius:12px;padding:12px;margin:10px 0}\n.tech{background:var(--card);border-radius:14px;padding:12px 14px;margin:10px 0}.tech summary{font-weight:600;cursor:pointer}.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:6px 0}\n.chip{border:1px solid var(--line);border-radius:16px;padding:5px 11px;font-size:15px;background:#fff}.chip.on{background:var(--blue);color:#fff;border-color:var(--blue)}\n.f{margin:8px 0}.f>span{display:block;font-size:14px;color:var(--sub);margin-bottom:3px}\n#sheet{position:fixed;inset:0;background:rgba(0,0,0,.35);display:none;align-items:flex-end;justify-content:center}#sheet>div{background:#fff;border-radius:16px 16px 0 0;max-width:640px;width:100%;padding:18px 16px 28px;max-height:85vh;overflow:auto}\n#sheet ul{padding-left:20px}:focus-visible{outline:3px solid #7FB0E8;outline-offset:2px}\n</style></head><body><main id=\"app\"><p class=\"sub\">\u2026</p></main><div id=\"sheet\"><div id=\"sheetIn\"></div></div>\n<script>\n'use strict';\nconst T = new URLSearchParams(location.search).get('t') || '';\nconst API = '../api.php';\nlet L = localStorage.getItem('setupLang') === 'en' ? 'en' : 'vi', D = null;\nconst V = (vi, en) => L === 'vi' ? vi : en, $ = (s, r = document) => r.querySelector(s), $$ = (s, r = document) => [...r.querySelectorAll(s)];\nconst esc = s => String(s ?? '').replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nasync function api(a, body) {\n  const r = await fetch(API + '?action=' + a + (body ? '' : '&t=' + encodeURIComponent(T)), body ? { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...body, t: T }) } : {});\n  let j = {}; try { j = await r.json(); } catch (e) {} if (!r.ok || j.error) { const e = new Error(j.error || ('HTTP ' + r.status)); e.code = r.status; throw e; } return j;\n}\n/* ---------- the questions (BANG-MAP-632 + TRA-LOI-632). k = the setting, v = its value; later = NailFlow sets it up later (turn_setup_notes) ---------- */\nconst DAYS = () => V('CN T2 T3 T4 T5 T6 T7', 'Sun Mon Tue Wed Thu Fri Sat').split(' ');\nconst QS = () => [\n  { id: 'q1', t: V('B\u1eb1ng s\u1ed1 turn nhau th\u00ec ai \u0111\u1ee9ng tr\u01b0\u1edbc?', 'Same number of turns \u2013 who goes first?'), k: 'turn_tie', o: [\n    ['clock', V('Ai clock in tr\u01b0\u1edbc', 'Who clocked in first'), 1], ['done', V('Ai l\u00e0m xong kh\u00e1ch tr\u01b0\u1edbc', 'Who finished their customer first')],\n    ['L:fixed', V('Th\u1ee9 t\u1ef1 c\u1ed1 \u0111\u1ecbnh (th\u00e2m ni\u00ean / ch\u1ee7 x\u1ebfp)', 'A fixed order (seniority / owner)')], ['L:rotate', V('Xoay v\u00f2ng theo ng\u00e0y', 'Rotate by day')],\n    ['L:yesterday', V('Ti\u1ebfp th\u1ee9 t\u1ef1 c\u1ee7a h\u00f4m qua', 'Continue yesterday\\'s order')], ['L:start', V('V\u1ec1 cu\u1ed1i h\u00e0ng khi B\u1eaeT \u0110\u1ea6U l\u00e0m', 'To the end of the line when STARTING')]] },\n  { id: 'q2', t: V('C\u00e1ch t\u00ednh turn', 'How turns are counted'), k: 'turn_multi', o: [\n    ['cust', V('M\u1ed7i kh\u00e1ch = 1 turn (d\u01b0\u1edbi m\u1ee9c $ b\u00ean d\u01b0\u1edbi th\u00ec theo d\u00f2ng \"Kh\u00e1ch d\u01b0\u1edbi m\u1ee9c\")', 'Each customer = 1 turn (under the $ line below: see \"Under the line\")'), 1],\n    ['svc', V('M\u1ed7i d\u1ecbch v\u1ee5 t\u1eeb $X = 1 turn', 'Each service from $X = 1 turn'), 0, 'turn_svc_amt'], ['per', V('Theo t\u1ed5ng ti\u1ec1n: m\u1ed7i $X = 1 turn', 'By money: every $X = 1 turn'), 0, 'turn_multi_amt'],\n    ['L:minutes', V('Theo th\u1eddi gian l\u00e0m (ph\u00fat)', 'By minutes worked')], ['L:15', V('Tr\u00ean $Y = 1.5 turn', 'Over $Y = 1.5 turns')]],\n    extra: () => `<div class=\"f\"><span>${V('M\u1ee9c $ cho 1 turn (0 = kh\u00e1ch n\u00e0o c\u0169ng t\u00ednh)', '$ for 1 turn (0 = every customer counts)')}</span><input class=\"n\" type=\"number\" min=\"0\" max=\"1000\" step=\"1\" data-k=\"turn_min\" value=\"${esc(D.turn.turn_min)}\"></div>\n      <div class=\"f\"><span>${V('Kh\u00e1ch d\u01b0\u1edbi m\u1ee9c \u0111\u00f3', 'A customer under that')}</span><select data-k=\"turn_under\">${[['half', V('N\u1eeda turn', 'Half a turn')], ['bonus', V('Bonus (h\u00e0ng ri\u00eang, kh\u00f4ng t\u00ednh turn)', 'Bonus (own rotation, no turn)')], ['none', V('Kh\u00f4ng t\u00ednh', 'Nothing')]].map(([v, l]) => `<option value=\"${v}\"${D.turn.turn_under === v ? ' selected' : ''}>${l}</option>`).join('')}</select></div>` },\n  { id: 'q4', t: V('Kh\u00e1ch g\u1ecdi \u0111\u00edch danh th\u1ee3 (request) / kh\u00e1ch h\u1eb9n c\u00f3 th\u1ee3', 'A customer who asks for a tech by name / booked with a tech'), k: 'turn_req_mode', o: [\n    ['none', V('Kh\u00f4ng t\u00ednh turn', 'No turn'), 1], ['count', V('T\u00ednh nh\u01b0 kh\u00e1ch th\u01b0\u1eddng', 'Counts like any customer')], ['half', V('N\u1eeda turn', 'Half a turn')],\n    ['L:keepfirst', V('Kh\u00f4ng t\u00ednh, nh\u01b0ng th\u1ee3 \u0111ang \u0111\u1ee9ng \u0111\u1ea7u th\u00ec m\u1ea5t l\u01b0\u1ee3t \u0111\u1ea7u', 'No turn, but a tech first in line loses that first place')]] },\n  { id: 'q5', t: V('Gi\u1eef th\u1ee3 cho kh\u00e1ch h\u1eb9n', 'Keep a tech for a booked customer'), num: ['turn_hold_min', 0, 120, V('Kh\u00f4ng nh\u1eadn walk-in khi h\u1eb9n b\u1eaft \u0111\u1ea7u trong \u2026 ph\u00fat (0 = ch\u1ec9 gi\u1eef \u0111\u00fang gi\u1edd h\u1eb9n)', 'No walk-in when the booking starts within \u2026 min (0 = only at the booking time)')] },\n  { id: 'q6', t: V('Th\u1ee3 l\u00e0m d\u1ecbch v\u1ee5 hi\u1ebfm (vd builder gel)', 'A tech who does a rare service (e.g. builder gel)'), k: 'turn_rare_keep', o: [\n    ['1', V('Gi\u1eef th\u1ee3 \u0111\u00f3 cho kh\u00e1ch c\u1ea7n, KH\u00d4NG m\u1ea5t turn', 'Keep that tech for the customer who needs it \u2013 no turn lost')], ['0', V('Kh\u00f4ng gi\u1eef: kh\u00e1ch c\u1ea7n th\u00ec giao th\u1ee3 bi\u1ebft l\u00e0m \u0111\u1ea7u h\u00e0ng, ng\u01b0\u1eddi b\u1ecb b\u1ecf qua gi\u1eef ch\u1ed7', 'Do not keep: the first tech in line who can do it; the ones skipped keep their place')],\n    ['L:keeplose', V('Gi\u1eef nh\u01b0ng m\u1ea5t turn', 'Keep, but lose the turn')], ['L:asreq', V('T\u00ednh nh\u01b0 request', 'Counts as a request')]] },\n  { id: 'q7', t: V('Bu\u1ed5i s\u00e1ng t\u00ednh turn t\u1eeb l\u00fac n\u00e0o', 'Morning: turns count from when'), k: 'turn_pre_open', o: [\n    ['1', V('Kh\u00e1ch b\u1eaft \u0111\u1ea7u l\u00fac 9:15 s\u00e1ng ho\u1eb7c s\u1edbm h\u01a1n (tr\u01b0\u1edbc gi\u1edd m\u1edf c\u1eeda) kh\u00f4ng t\u00ednh', 'A customer started at 9:15 AM or earlier (before opening) counts nothing')],\n    ['0', V('T\u00ednh t\u1eeb kh\u00e1ch \u0111\u1ea7u ti\u00ean / t\u1eeb l\u00fac m\u1edf c\u1eeda', 'From the first customer / from opening')], ['L:othertime', V('Kh\u00f4ng t\u00ednh tr\u01b0\u1edbc m\u1ed9t gi\u1edd kh\u00e1c (ghi gi\u1edd \u1edf ghi ch\u00fa)', 'Not counted before another time (write it in the note)')]] },\n  { id: 'q8', t: V('Th\u1ee3 t\u1eeb ch\u1ed1i kh\u00e1ch', 'A tech turns a customer down'), k: 'turn_skip_max', o: [\n    ['1', V('M\u1ea5t l\u01b0\u1ee3t, xu\u1ed1ng cu\u1ed1i h\u00e0ng', 'Loses the turn, to the end of the line'), 1], ['N', V('Gi\u1eef ch\u1ed7, qu\u00e1 \u2026 l\u1ea7n/ng\u00e0y th\u00ec xu\u1ed1ng cu\u1ed1i', 'Keeps the place; after \u2026 times a day to the end')], ['0', V('Lu\u00f4n gi\u1eef ch\u1ed7', 'Always keeps the place')]] },\n  { id: 'q9', t: V('Th\u1ee3 \u0111i \u0103n / ngh\u1ec9', 'A tech on a break'), k: 'turn_brk_max', o: [\n    ['0', V('Gi\u1eef ch\u1ed7, ngh\u1ec9 bao l\u00e2u c\u0169ng \u0111\u01b0\u1ee3c', 'Keeps the place however long'), 1], ['N', V('Ngh\u1ec9 qu\u00e1 \u2026 ph\u00fat th\u00ec xu\u1ed1ng cu\u1ed1i h\u00e0ng', 'Over \u2026 min: to the end of the line')]] },\n  { id: 'q10', t: V('Kh\u00e1ch b\u1ecf v\u1ec1 / \u0111\u1ed5i th\u1ee3 gi\u1eefa ch\u1eebng', 'A customer leaves / changes tech midway'), o: [['L:giveback', V('Tr\u1ea3 l\u1ea1i turn cho th\u1ee3 c\u0169', 'Give the turn back to the first tech')], ['L:keep', V('V\u1eabn t\u00ednh cho th\u1ee3 c\u0169', 'Still counts for the first tech')]] },\n  { id: 'q11', t: V('2 th\u1ee3 c\u00f9ng l\u00e0m 1 kh\u00e1ch', 'Two techs on one customer'), o: [['=split', V('M\u1ed7i th\u1ee3 t\u00ednh theo ph\u1ea7n d\u1ecbch v\u1ee5 c\u1ee7a m\u00ecnh', 'Each tech by their own services'), 1], ['L:half', V('M\u1ed7i ng\u01b0\u1eddi 1/2 turn', 'Half a turn each')], ['L:main', V('Th\u1ee3 ch\u00ednh 1 turn, th\u1ee3 ph\u1ee5 0', 'Main tech 1, helper 0')]] },\n  { id: 'q12', t: V('Ai ch\u1ecdn th\u1ee3 cho kh\u00e1ch walk-in', 'Who picks the tech for a walk-in'), k: 'turn_auto_on', o: [['1', V('App t\u1ef1 giao ng\u01b0\u1eddi \u0111\u1ea7u h\u00e0ng', 'The app gives it to the first in line'), 1], ['0', V('L\u1ec5 t\u00e2n ch\u1ecdn, app ch\u1ec9 g\u1ee3i \u00fd', 'The desk picks, the app suggests')]],\n    extra: () => `<label class=\"o\"><input type=\"checkbox\" data-k=\"ck_pick_tech\"${D.turn.ck_pick_tech ? ' checked' : ''}><span>${V('Kh\u00e1ch \u0111\u01b0\u1ee3c t\u1ef1 ch\u1ecdn th\u1ee3 tr\u00ean iPad check-in (= request)', 'Customers may pick a tech on the check-in iPad (= a request)')}</span></label>` },\n  { id: 'q13', t: V('Kh\u00e1ch quay l\u1ea1i S\u1eecA mi\u1ec5n ph\u00ed', 'A customer back for a FREE fix'), o: [['=nofix', V('Kh\u00f4ng t\u00ednh turn', 'No turn'), 1], ['L:otherhalf', V('Th\u1ee3 kh\u00e1c s\u1eeda \u0111\u01b0\u1ee3c n\u1eeda turn', 'Another tech fixing gets half a turn')], ['L:count', V('T\u00ednh b\u00ecnh th\u01b0\u1eddng', 'Counts as usual')]] },\n];\nconst cur = q => { if (!q.k) return q.o.find(o => o[0][0] === '=')?.[0] || ''; const v = String(D.turn[q.k]); if (q.k === 'turn_skip_max' || q.k === 'turn_brk_max') return v === '0' ? '0' : (q.k === 'turn_skip_max' && v === '1' ? '1' : 'N'); return v; };\nfunction qHtml(q) {\n  if (q.num) { const [k, lo, hi, lab] = q.num; return `<div class=\"q\" data-q=\"${q.id}\"><h3>${esc(q.t)}</h3><div class=\"f\"><span>${esc(lab)}</span><input class=\"n\" type=\"number\" min=\"${lo}\" max=\"${hi}\" data-k=\"${k}\" value=\"${esc(D.turn[k])}\"></div></div>`; }\n  const c = cur(q), nv = q.k === 'turn_skip_max' ? Math.max(1, (+D.turn.turn_skip_max || 3) - 1) : (+D.turn.turn_brk_max || 30);\n  return `<div class=\"q\" data-q=\"${q.id}\"><h3>${esc(q.t)}</h3>` + q.o.map(([v, l, pop, amt]) => {\n    const later = v.startsWith('L:'), same = v.startsWith('=');\n    const num = v === 'N' ? ` <input class=\"n\" type=\"number\" min=\"1\" max=\"${q.k === 'turn_brk_max' ? 600 : 19}\" data-n=\"${q.id}\" value=\"${nv}\">` : (amt ? ` <input class=\"n\" type=\"number\" min=\"1\" max=\"1000\" data-k=\"${amt}\" value=\"${esc(D.turn[amt])}\">` : '');\n    return `<label class=\"o\"><input type=\"radio\" name=\"${q.id}\" value=\"${esc(v)}\"${v === c ? ' checked' : ''}><span>${esc(l)}${num}${pop ? `<span class=\"tag pop\">${V('Ph\u1ed5 bi\u1ebfn', 'Common')}</span>` : ''}${v === c && !later ? `<span class=\"tag now\">${V('\u0110ang d\u00f9ng', 'Now')}</span>` : ''}${same ? `<span class=\"tag now\">${V('App l\u00e0m s\u1eb5n', 'Built in')}</span>` : ''}${later ? `<span class=\"tag later\">${V('NailFlow s\u1ebd li\u00ean h\u1ec7 c\u00e0i th\u00eam', 'NailFlow will set this up')}</span>` : ''}</span></label>`; }).join('')\n    + (q.extra ? q.extra() : '') + `<div class=\"f\"><textarea data-note=\"${q.id}\" placeholder=\"${V('Kh\u00e1c / ghi ch\u00fa', 'Other / note')}\"></textarea></div></div>`;\n}\n/* the page's answers -> the settings to send + the notes */\nfunction turnOut() {\n  const o = {}, notes = [];\n  for (const q of QS()) {\n    const r = $(`[name=\"${q.id}\"]:checked`), v = r ? r.value : '', nt = ($(`[data-note=\"${q.id}\"]`) || {}).value || '';\n    if (v.startsWith('L:') || nt.trim()) notes.push({ q: q.id, pick: v.startsWith('L:') ? v.slice(2) : '', text: nt.trim().slice(0, 500) });\n    if (q.num) { o[q.num[0]] = +$(`[data-k=\"${q.num[0]}\"]`).value; continue; }\n    if (!q.k || !v || v.startsWith('L:') || v.startsWith('=')) continue;\n    if (v === 'N') { const n = +$(`[data-n=\"${q.id}\"]`).value || 1; o[q.k] = q.k === 'turn_skip_max' ? n + 1 : n; }\n    else o[q.k] = q.k === 'turn_rare_keep' || q.k === 'turn_pre_open' || q.k === 'turn_auto_on' || q.k === 'turn_skip_max' || q.k === 'turn_brk_max' ? +v : v;\n    if (q.id === 'q2') { const amt = q.o.find(x => x[0] === v)?.[3]; if (amt) o[amt] = +$(`[data-k=\"${amt}\"]`).value; }\n  }\n  o.turn_min = +$('[data-k=\"turn_min\"]').value; o.turn_under = $('[data-k=\"turn_under\"]').value; o.ck_pick_tech = $('[data-k=\"ck_pick_tech\"]').checked ? 1 : 0;\n  return { set: o, notes };\n}\nconst LAB = { turn_tie: 'q1', turn_multi: 'q2', turn_svc_amt: 'q2', turn_multi_amt: 'q2', turn_min: 'q2', turn_under: 'q2', turn_req_mode: 'q4', turn_hold_min: 'q5', turn_rare_keep: 'q6', turn_pre_open: 'q7', turn_skip_max: 'q8', turn_brk_max: 'q9', turn_auto_on: 'q12', ck_pick_tech: 'q12' };\nfunction confirmSheet(lines, go) {\n  $('#sheetIn').innerHTML = `<h2 style=\"margin-top:0\">${V('S\u1ebd \u0111\u1ed5i', 'Will change')}</h2>` + (lines.length ? `<ul>${lines.map(l => `<li>${esc(l)}</li>`).join('')}</ul>` : `<p>${V('Kh\u00f4ng c\u00f3 g\u00ec thay \u0111\u1ed5i.', 'Nothing changes.')}</p>`)\n    + `<button class=\"btn\" id=\"go\">${V('L\u01b0u', 'Save')}</button><button class=\"btn alt\" id=\"back\">${V('Quay l\u1ea1i s\u1eeda', 'Back')}</button><div id=\"sheetMsg\"></div>`;\n  $('#sheet').style.display = 'flex'; $('#back').onclick = () => { $('#sheet').style.display = 'none'; };\n  $('#go').onclick = async () => { $('#go').disabled = true; try { await go(); $('#sheet').style.display = 'none'; } catch (e) { $('#sheetMsg').innerHTML = `<div class=\"err\">${esc(e.message)}</div>`; $('#go').disabled = false; } };\n}\n/* ---------- staff ---------- */\nfunction techHtml(s, i) {\n  const pm = Object.entries(D.payMethods), days = DAYS();\n  return `<details class=\"tech\" data-i=\"${i}\"${s.id ? '' : ' open'}><summary>${esc(s.name || V('Th\u1ee3 m\u1edbi', 'New tech'))}</summary>\n    <div class=\"f\"><span>${V('T\u00ean', 'Name')}</span><input type=\"text\" data-f=\"name\" maxlength=\"40\" value=\"${esc(s.name)}\"></div>\n    <div class=\"f\"><span>${V('S\u1ed1 \u0111i\u1ec7n tho\u1ea1i (10 s\u1ed1)', 'Phone (10 digits)')}</span><input type=\"tel\" data-f=\"phone\" value=\"${esc(s.phone)}\"></div>\n    <div class=\"f\"><span>${V('Ng\u00e0y ngh\u1ec9 c\u1ed1 \u0111\u1ecbnh', 'Days off every week')}</span><div class=\"row\">${days.map((d, k) => `<button type=\"button\" class=\"chip${s.offDays.includes(k) ? ' on' : ''}\" data-off=\"${k}\">${d}</button>`).join('')}</div></div>\n    <div class=\"f\"><span>${V('D\u1ecbch v\u1ee5 l\u00e0m \u0111\u01b0\u1ee3c', 'Services')}</span><label class=\"o\"><input type=\"checkbox\" data-f=\"skillAll\"${s.skillAll ? ' checked' : ''}><span>${V('L\u00e0m \u0111\u01b0\u1ee3c T\u1ea4T C\u1ea2', 'Can do ALL services')}</span></label>\n      <div class=\"row\">${D.cats.map(c => `<button type=\"button\" class=\"chip${s.skillCats.includes(c.key) ? ' on' : ''}\" data-cat=\"${esc(c.key)}\">${esc(c.icon)} ${esc(c.key)}</button>`).join('')}</div></div>\n    <div class=\"row\"><div class=\"f\"><span>Commission %</span><input class=\"n\" type=\"number\" min=\"0\" max=\"100\" step=\"0.5\" data-f=\"commission\" value=\"${esc(s.commission)}\"></div>\n      <div class=\"f\"><span>${V('Tr\u1ea3 b\u1eb1ng', 'Paid by')}</span><select data-f=\"payMethod\">${pm.map(([k, l]) => `<option value=\"${k}\"${s.payMethod === k ? ' selected' : ''}>${esc(l)}</option>`).join('')}</select></div>\n      <div class=\"f\"><span>${V('% check (mix)', '% check (mix)')}</span><input class=\"n\" type=\"number\" min=\"0\" max=\"100\" data-f=\"mixCheck\" value=\"${esc(s.mixCheck)}\" placeholder=\"${V('nh\u01b0 ti\u1ec7m', 'salon')}\"></div></div>\n    <label class=\"o\"><input type=\"checkbox\" data-f=\"online\"${s.online ? ' checked' : ''}><span>${V('Cho kh\u00e1ch \u0111\u1eb7t online', 'Customers can book online')}</span></label>\n    <label class=\"o\"><input type=\"checkbox\" data-f=\"deskOk\"${s.deskOk ? ' checked' : ''}><span>${V('\u0110\u01b0\u1ee3c l\u00e0m l\u1ec5 t\u00e2n (check out / b\u00e1n gift card)', 'Front desk: check out / sell gift cards')}</span></label>\n    <div class=\"f\"><span>${V('Gi\u1ecdng b\u00e1o t\u1edbi l\u01b0\u1ee3t', 'YOUR TURN voice')}</span><select data-f=\"voice\"><option value=\"vi\"${s.voice === 'vi' ? ' selected' : ''}>Ti\u1ebfng Vi\u1ec7t</option><option value=\"en\"${s.voice !== 'vi' ? ' selected' : ''}>English</option></select></div>\n    <div class=\"f\"><span>${V('Ghi ch\u00fa', 'Note')}</span><input type=\"text\" data-f=\"payNote\" maxlength=\"200\" value=\"${esc(s.payNote)}\"></div>\n    ${s.id ? `<label class=\"o\"><input type=\"checkbox\" data-f=\"off\"><span>${V('Kh\u00f4ng c\u00f2n l\u00e0m \u1edf ti\u1ec7m (t\u1eaft \u2013 l\u1ecbch s\u1eed, l\u01b0\u01a1ng gi\u1eef nguy\u00ean)', 'No longer works here (turned off \u2013 history and pay kept)')}</span></label>` : ''}</details>`;\n}\nfunction techOut(el) {\n  const g = f => $(`[data-f=\"${f}\"]`, el), mix = g('mixCheck').value.trim();\n  return { name: g('name').value.trim().toUpperCase(), phone: g('phone').value.trim(), offDays: $$('[data-off].on', el).map(x => +x.dataset.off), skillAll: g('skillAll').checked ? 1 : 0,\n    skillCats: $$('[data-cat].on', el).map(x => x.dataset.cat), commission: +g('commission').value || 0, payMethod: g('payMethod').value, mixCheck: mix === '' ? '' : +mix,\n    online: g('online').checked ? 1 : 0, deskOk: g('deskOk').checked ? 1 : 0, voice: g('voice').value, payNote: g('payNote').value.trim(), off: g('off') ? g('off').checked : false };\n}\nconst same = (a, b) => JSON.stringify(a) === JSON.stringify(b);\nfunction staffDiff() {\n  const out = [];\n  $$('details.tech').forEach(el => { const i = +el.dataset.i, s = D.staffEdit[i], n = techOut(el), ch = [];\n    if (!s.id && !n.name) return;\n    for (const k of ['name', 'phone', 'commission', 'payMethod', 'mixCheck', 'online', 'deskOk', 'voice', 'payNote', 'skillAll']) if (String(n[k]) !== String(s[k] ?? '')) ch.push(k);\n    if (!same([...n.offDays].sort(), [...s.offDays].sort())) ch.push(V('ng\u00e0y ngh\u1ec9', 'days off')); if (!same([...n.skillCats].sort(), [...s.skillCats].sort())) ch.push(V('d\u1ecbch v\u1ee5', 'services'));\n    if (n.off) out.push({ s, n, line: (n.name || s.name) + ': ' + V('t\u1eaft (kh\u00f4ng c\u00f2n l\u00e0m)', 'turned off') });\n    else if (!s.id) out.push({ s, n, line: V('Th\u00eam th\u1ee3 ', 'New tech ') + n.name }); else if (ch.length) out.push({ s, n, line: s.name + ': ' + ch.join(', ') }); });\n  return out;\n}\n/* ---------- the page ---------- */\nfunction render() {\n  document.documentElement.lang = L;\n  const tDone = D.done.includes('turn'), sDone = D.done.includes('staff'), days = DAYS();\n  $('#app').innerHTML = `<header>${D.logo ? `<img src=\"../${esc(D.logo)}\" alt=\"\">` : ''}<div><h1>${esc(D.salon)}</h1><div class=\"sub\">${V('C\u00e0i \u0111\u1eb7t ti\u1ec7m \u00b7 link d\u00f9ng t\u1edbi ', 'Salon setup \u00b7 link works until ')}${esc(D.exp)}</div></div><button class=\"lang\" id=\"lang\">${L === 'vi' ? 'English' : 'Ti\u1ebfng Vi\u1ec7t'}</button></header>\n    <p class=\"sub\">${V('\u0110\u00e3 ch\u1ecdn s\u1eb5n theo c\u00e0i \u0111\u1eb7t HI\u1ec6N T\u1ea0I c\u1ee7a ti\u1ec7m. S\u1eeda ch\u1ed7 c\u1ea7n \u0111\u1ed5i r\u1ed3i b\u1ea5m L\u01b0u \u2013 m\u1ed7i ph\u1ea7n l\u01b0u 1 l\u1ea7n.', 'Filled in with the salon\\'s CURRENT settings. Change what you need, then Save \u2013 each part is saved once.')}</p>\n    <h2>1. ${V('Lu\u1eadt chia turn', 'Turn rules')}</h2>${tDone ? `<div class=\"ok\">\u2713 ${V('\u0110\u00e3 l\u01b0u.', 'Saved.')}</div>` : QS().map(qHtml).join('') + `<button class=\"btn\" id=\"saveTurn\">${V('L\u01b0u lu\u1eadt turn', 'Save turn rules')}</button><div id=\"turnMsg\"></div>`}\n    <h2>2. ${V('Danh s\u00e1ch th\u1ee3', 'Techs')}</h2>${sDone ? `<div class=\"ok\">\u2713 ${V('\u0110\u00e3 l\u01b0u.', 'Saved.')}</div>` : `<p class=\"sub\">${V('M\u1ed7i th\u1ee3 t\u1ef1 \u0111\u1eb7t PIN tr\u00ean trang /tech/ nh\u01b0 hi\u1ec7n nay \u2013 \u1edf \u0111\u00e2y kh\u00f4ng c\u00f3 PIN.', 'Each tech sets their own PIN on /tech/ as today \u2013 no PIN here.')}</p>\n      <div class=\"q\"><div class=\"f\"><span>${V('Tu\u1ea7n l\u01b0\u01a1ng b\u1eaft \u0111\u1ea7u', 'Payroll week starts on')}</span><select id=\"wk\">${days.map((d, k) => `<option value=\"${k}\"${D.shop.payroll_week_start === k ? ' selected' : ''}>${d}</option>`).join('')}</select></div>\n        <div class=\"f\"><span>${V('Ng\u00e0y ti\u1ec7m \u0111\u00f3ng c\u1eeda', 'Days the salon is closed')}</span><div class=\"row\">${days.map((d, k) => `<button type=\"button\" class=\"chip${D.shop.closed.includes(k) ? ' on' : ''}\" data-cl=\"${k}\">${d}</button>`).join('')}</div></div></div>\n      <div id=\"techs\">${D.staffEdit.map(techHtml).join('')}</div><button class=\"btn alt\" id=\"addTech\">+ ${V('Th\u00eam th\u1ee3', 'Add a tech')}</button><button class=\"btn\" id=\"saveStaff\">${V('L\u01b0u danh s\u00e1ch th\u1ee3', 'Save techs')}</button><div id=\"staffMsg\"></div>`}`;\n  $('#lang').onclick = () => { L = L === 'vi' ? 'en' : 'vi'; try { localStorage.setItem('setupLang', L); } catch (e) {} render(); };\n  $$('[data-off],[data-cat],[data-cl]').forEach(b => b.onclick = () => b.classList.toggle('on'));\n  if (!tDone) $('#saveTurn').onclick = () => { const { set, notes } = turnOut(), lines = [];\n    for (const [k, v] of Object.entries(set)) if (String(v) !== String(D.turn[k])) lines.push(`${QS().find(q => q.id === LAB[k])?.t || k}: ${D.turn[k]} \u2192 ${v}`);\n    notes.forEach(n => lines.push(`${QS().find(q => q.id === n.q).t}: ${n.pick ? V('(NailFlow c\u00e0i th\u00eam) ', '(NailFlow sets up) ') + n.pick : ''} ${n.text}`));\n    confirmSheet(lines, async () => { await api('setup_turn', { ...set, notes }); D.done.push('turn'); render(); $('#turnMsg').innerHTML = ''; window.scrollTo(0, 0); }); };\n  if (!sDone) {\n    $('#addTech').onclick = () => { D.staffEdit.push({ id: 0, name: '', phone: '', offDays: [], skillAll: 1, skillCats: [], commission: 50, payMethod: 'check', mixCheck: '', payNote: '', online: 1, deskOk: 0, voice: 'vi' });\n      $('#techs').insertAdjacentHTML('beforeend', techHtml(D.staffEdit[D.staffEdit.length - 1], D.staffEdit.length - 1)); $$('#techs details:last-child [data-off], #techs details:last-child [data-cat]').forEach(b => b.onclick = () => b.classList.toggle('on')); };\n    $('#saveStaff').onclick = () => { const list = staffDiff(), wk = +$('#wk').value, cl = $$('[data-cl].on').map(x => +x.dataset.cl), lines = list.map(x => x.line), shopCh = wk !== D.shop.payroll_week_start || !same([...cl].sort(), [...D.shop.closed].sort());\n      if (shopCh) lines.unshift(V('Tu\u1ea7n l\u01b0\u01a1ng / ng\u00e0y \u0111\u00f3ng c\u1eeda', 'Payroll week / closed days'));\n      confirmSheet(lines, async () => {\n        if (shopCh) await api('setup_shop', { payroll_week_start: wk, closed: cl });\n        for (const x of list) { const m = x.s.id ? '\u0111\u00e3 l\u01b0u t\u1edbi ' + x.s.name : '';\n          try { if (x.n.off) await api('setup_staff_off', { id: x.s.id }); else { const b = { ...x.n, id: x.s.id }; delete b.off; const r = await api('setup_staff_one', b); x.s.id = r.id || x.s.id; Object.assign(x.s, x.n); } }\n          catch (e) { throw new Error((x.n.name || x.s.name) + ': ' + e.message); } }\n        await api('setup_staff_end', {}); D.done.push('staff'); render(); });\n    };\n  }\n}\n(async () => {\n  if (!T) { $('#app').innerHTML = `<p class=\"err\">${V('Link kh\u00f4ng \u0111\u00fang.', 'This link is not right.')}</p>`; return; }\n  try { D = await api('setup_info'); D.staffEdit = D.staff.map(s => ({ ...s })); document.title = D.salon; render(); }\n  catch (e) { $('#app').innerHTML = `<p class=\"err\">${esc(e.message)}</p>`; }\n})();\n</script></body></html>\n", "assets/admin/setup-link.js": "/* (2.99.632 - LENH 632) Settings -> Turn: \"\ud83d\udd17 Salon setup link\" \u2013 a link on the salon's own address (7 days, each part saved once) for the turn rules\n   and the techs, and \"Undo the link setup\" (the old values saved back with the SAME actions as these screens: save_settings / save_staff_one / remove_staff).\n   Loaded after turn-easy.js (LAZY_FILES.settings). */\n'use strict';\n(function () {\n  const orig = SET_PAGES.turn;\n  if (typeof orig !== 'function' || orig.__setup) return;\n  SET_PAGES.turn = function (b) {\n    const r = orig.apply(this, arguments);\n    try {\n      const card = document.createElement('div'); card.className = 'card'; card.id = 'suCard';\n      card.innerHTML = `<h3 style=\"margin-top:0\">${LV('\ud83d\udd17 Salon setup link', '\ud83d\udd17 Link c\u00e0i \u0111\u1eb7t ti\u1ec7m')}</h3>\n        <p class=\"hint\" style=\"margin:0 0 8px\">${LV('Send it to the salon owner: they pick the turn rules and fix / add the techs on their phone, no login. 7 days; each part is saved once; a new link stops the old one.', 'G\u1eedi cho ch\u1ee7 ti\u1ec7m: ch\u1ecdn lu\u1eadt turn, s\u1eeda / th\u00eam th\u1ee3 tr\u00ean \u0111i\u1ec7n tho\u1ea1i, kh\u00f4ng c\u1ea7n \u0111\u0103ng nh\u1eadp. D\u00f9ng 7 ng\u00e0y; m\u1ed7i ph\u1ea7n l\u01b0u 1 l\u1ea7n; t\u1ea1o link m\u1edbi th\u00ec link c\u0169 h\u1ebft.')}</p>\n        <div class=\"row\"><button type=\"button\" class=\"btn primary\" id=\"suNew\">${LV('Make a setup link', 'T\u1ea1o link c\u00e0i \u0111\u1eb7t')}</button><button type=\"button\" class=\"btn\" id=\"suUndo\">${LV('Undo the link setup', 'Ho\u00e0n t\u00e1c l\u1ea7n c\u00e0i b\u1eb1ng link')}</button></div><div id=\"suMsg\"></div>`;\n      const at = b.querySelector('#teCard') || b.querySelector('#trCard') || b.lastElementChild; if (at && at.parentNode) at.parentNode.insertBefore(card, at.nextSibling); else b.appendChild(card);\n      const msg = (h) => { card.querySelector('#suMsg').innerHTML = h; };\n      api('setup_prev').then(p => { const n = p && p.notes && p.notes.notes; if (n && n.length) msg(`<p class=\"hint\">${LV('The salon asked for (NailFlow sets up): ', 'Ti\u1ec7m ch\u1ecdn th\u00eam (NailFlow c\u00e0i): ')}${n.map(x => esc(x.q + ' ' + x.pick + ' ' + x.text)).join(' \u00b7 ')}</p>`); }).catch(() => {});\n      card.querySelector('#suNew').addEventListener('click', async () => {\n        if (!confirm(LV('Make a new link? The old link stops working.', 'T\u1ea1o link m\u1edbi? Link c\u0169 s\u1ebd h\u1ebft d\u00f9ng \u0111\u01b0\u1ee3c.'))) return;\n        try { const j = await api('setup_new', {}); msg(`<p class=\"hint\">${LV('Copy and send:', 'Ch\u00e9p v\u00e0 g\u1eedi:')}</p><input class=\"inp\" readonly value=\"${esc(j.url)}\" style=\"width:100%\" onclick=\"this.select()\">`);\n          try { await navigator.clipboard.writeText(j.url); } catch (e) {} } catch (e) { oops(e); } });\n      card.querySelector('#suUndo').addEventListener('click', async () => {\n        try { const p = await api('setup_prev'); const st = p.staff || {}, rows = Object.values(st.rows || {});\n          if (!p.turn && !rows.length && !(st.new || []).length && !st.shop) { msg(`<p class=\"hint\">${LV('Nothing to undo.', 'Kh\u00f4ng c\u00f3 g\u00ec \u0111\u1ec3 ho\u00e0n t\u00e1c.')}</p>`); return; }\n          if (!confirm(LV('Put back the values from before the link setup?', 'Tr\u1ea3 l\u1ea1i gi\u00e1 tr\u1ecb tr\u01b0\u1edbc khi c\u00e0i b\u1eb1ng link?'))) return;\n          if (p.turn) { await api('save_settings', p.turn); await api('setup_prev_clear', { part: 'turn' }); }\n          for (const x of rows) await api('save_staff_one', x);\n          for (const id of (st.new || [])) await api('remove_staff', { id });\n          if (st.shop) await api('save_settings', st.shop);\n          if (rows.length || (st.new || []).length || st.shop) await api('setup_prev_clear', { part: 'staff' });\n          const off = (st.off || []).map(id => (st.rows || {})[String(id)]?.name || ('#' + id));\n          msg(`<p class=\"hint\">\u2713 ${LV('Undone.', '\u0110\u00e3 ho\u00e0n t\u00e1c.')}${off.length ? ' ' + LV('Turned off through the link (add them back in Staff): ', 'Th\u1ee3 \u0111\u00e3 t\u1eaft qua link (th\u00eam l\u1ea1i trong Staff): ') + esc(off.join(', ')) : ''}</p>`); saved();\n        } catch (e) { oops(e); } });\n    } catch (e) {}\n    return r;\n  };\n  SET_PAGES.turn.__setup = 1; SET_PAGES.turn.__easy = orig.__easy;\n})();\n"}""")
plan = []; bad = 0
